import sys

def string_similarity(s):
	(l, r, n) = (0, 0, len(s))
	z = [0] * n
	for i in range(1, n):
		if i <= r and z[i - l] < r - i + 1:
			z[i] = z[i - l]
		else:
			l = i
			if i > r:
				r = i
			while r < n and s[r - l] == s[r]:
				r += 1
			z[i] = r - l
			r -= 1
	return n + sum(z)
T = int(sys.stdin.readline())
for i in range(T):
	print(string_similarity(sys.stdin.readline().strip()))
